module SimTop(
  input         clock,
                reset,
                cpuClock,
                coreSel,
  output [15:0] externalPins_mygpio_out,
  input  [15:0] externalPins_mygpio_in,
  output [7:0]  externalPins_mygpio_seg_0,
                externalPins_mygpio_seg_1,
                externalPins_mygpio_seg_2,
                externalPins_mygpio_seg_3,
                externalPins_mygpio_seg_4,
                externalPins_mygpio_seg_5,
                externalPins_mygpio_seg_6,
                externalPins_mygpio_seg_7,
  input         externalPins_uart0_rx,
  output        externalPins_uart0_tx
);

  wire       _flash_miso;
  wire       _asic_spi_sck;
  wire       _asic_spi_ss;
  wire       _asic_spi_mosi;
  wire       _asic_psram_sck_o;
  wire [2:0] _asic_psram_nss_o;
  wire       _psram_dio_0_wire;
  wire       _psram_dio_1_wire;
  wire       _psram_dio_2_wire;
  wire       _psram_dio_3_wire;
  asicTop asic (
    .clock_pad_i  (clock),
    .clock_pad_o  (/* unused */),
    .cpuClock     (cpuClock),
    .resetn_pad_i (~reset),
    .uart0_rx     (externalPins_uart0_rx),
    .uart0_tx     (externalPins_uart0_tx),
    .spi_sck      (_asic_spi_sck),
    .spi_ss       (_asic_spi_ss),
    .spi_mosi     (_asic_spi_mosi),
    .spi_miso     (_flash_miso),
    .psram_sck_o  (_asic_psram_sck_o),
    .psram_nss_o  (_asic_psram_nss_o),
    .psram_dio_0  (_psram_dio_0_wire),
    .psram_dio_1  (_psram_dio_1_wire),
    .psram_dio_2  (_psram_dio_2_wire),
    .psram_dio_3  (_psram_dio_3_wire),
    .mygpio_out   (externalPins_mygpio_out),
    .mygpio_in    (externalPins_mygpio_in),
    .mygpio_seg_0 (externalPins_mygpio_seg_0),
    .mygpio_seg_1 (externalPins_mygpio_seg_1),
    .mygpio_seg_2 (externalPins_mygpio_seg_2),
    .mygpio_seg_3 (externalPins_mygpio_seg_3),
    .mygpio_seg_4 (externalPins_mygpio_seg_4),
    .mygpio_seg_5 (externalPins_mygpio_seg_5),
    .mygpio_seg_6 (externalPins_mygpio_seg_6),
    .mygpio_seg_7 (externalPins_mygpio_seg_7)
  );
  flash flash (
    .sck  (_asic_spi_sck),
    .ss   (_asic_spi_ss),
    .mosi (_asic_spi_mosi),
    .miso (_flash_miso)
  );
  ESPWrapper #(
    .nss(4)
  ) espPsram (
    .sck_o (_asic_psram_sck_o),
    .nss_o ({1'h0, _asic_psram_nss_o}),
    .dio_0 (_psram_dio_0_wire),
    .dio_1 (_psram_dio_1_wire),
    .dio_2 (_psram_dio_2_wire),
    .dio_3 (_psram_dio_3_wire)
  );
endmodule

module ElaborateTop(
  input clock,
        reset
);

  SimTop dut (
    .clock                     (clock),
    .reset                     (reset),
    .cpuClock                  (1'h0),
    .coreSel                   (1'h0),
    .externalPins_mygpio_out   (/* unused */),
    .externalPins_mygpio_in    (16'h0),
    .externalPins_mygpio_seg_0 (/* unused */),
    .externalPins_mygpio_seg_1 (/* unused */),
    .externalPins_mygpio_seg_2 (/* unused */),
    .externalPins_mygpio_seg_3 (/* unused */),
    .externalPins_mygpio_seg_4 (/* unused */),
    .externalPins_mygpio_seg_5 (/* unused */),
    .externalPins_mygpio_seg_6 (/* unused */),
    .externalPins_mygpio_seg_7 (/* unused */),
    .externalPins_uart0_rx     (1'h0),
    .externalPins_uart0_tx     (/* unused */)
  );
endmodule


// ----- 8< ----- FILE "./ESPWrapper.v" ----- 8< -----

module ESPWrapper #(
  parameter nss = 4
)(
  input sck_o,
  input [nss-1:0] nss_o,
  inout dio_0,
  inout dio_1,
  inout dio_2,
  inout dio_3
);
  ESP_PSRAM64H psram(
   .sclk(sck_o),
   .csn(nss_o[0]),
   .sio({dio_3, dio_2, dio_1, dio_0})  // bidirection for inout
 );
endmodule
    
